function patternRepeatingLetterTriangle(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    const char = String.fromCharCode(65 + i);
    for (let j = 0; j <= i; j++) {
      row += char;
    }
    rows.push(row);
  }
  return rows.join('\n');
}

